const rows = [];

for (const item of $input.all()) {
  const data = item.json;

  if (!data.merchant_id || !Array.isArray(data.items)) {
    continue;
  }

  for (const product of data.items) {
    rows.push({
      json: {
        merchant_id: data.merchant_id,
        sku: String(product.sku).toUpperCase(),
        qty: Number(product.qty),
        synced_at: data.as_of
      }
    });
  }
}

// Jika tidak ada stok yang berhasil dinormalisasi,
// keluarkan satu item penanda agar IF tetap berjalan.
if (rows.length === 0) {
  return [
    {
      json: {
        sync_empty: true,
        reason: "Tidak ada baris stok yang berhasil dinormalisasi"
      }
    }
  ];
}

return rows;

