parameters.jsCode:
const kpi = $('Hitung KPI Harian').first().json;
const result = $input.first().json;

let reasons = result.alasan_batal ?? [];

if (typeof reasons === 'string') {
  try {
    reasons = JSON.parse(reasons);
  } catch {
    reasons = [];
  }
}

if (!Array.isArray(reasons)) {
  reasons = [];
}

const reasonsText = reasons.length
  ? reasons.map((r, i) =>
      `${i + 1}. ${r.alasan_batal}: ${r.jumlah_pembatalan} order`
    ).join('\n')
  : 'Tidak ada pembatalan tercatat.';

const message = [
  '📊 H8MART — DAILY OPS DIGEST',
  '',
  `Tanggal data: ${kpi.tanggal_digest}`,
  `Total order: ${kpi.total_orders}`,
  `Order dibatalkan: ${kpi.cancelled_orders}`,
  `Cancellation rate: ${kpi.cancel_rate_pct ?? 0}%`,
  `SLA ≤30 menit: ${kpi.sla_30m_pct ?? 0}%`,
  '',
  '🔎 Alasan pembatalan — Seluruh Merchant:',
  reasonsText,
  '',
  'Sumber: PostgreSQL H8Mart'
].join('\n');

return [{
  json: {
    ...kpi,
    merchant_id: 'ALL',
    alasan_batal: reasons,
    digest_message: message
  }
}];

